\set ON_ERROR_STOP on
create function pg_temp.assert_true(ok boolean, label text) returns void language plpgsql as $$
begin if ok is not true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.expect_error(statement text, expected text, label text) returns void language plpgsql as $$
begin
  begin execute statement;
  exception when others then
    if sqlstate = expected then return; end if;
    raise exception 'FAIL: % expected %, received %',label,expected,sqlstate;
  end;
  raise exception 'FAIL: % unexpectedly allowed',label;
end $$;
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
select pg_temp.assert_true((select count(*)=2 from public.staff_directory),'admin directory: active staff only');
insert into public.organizations(id,name,relationship_owner) values('20000000-0000-4000-8000-000000000001','Synthetic Organization A','10000000-0000-4000-8000-000000000002');
update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000003' where id='20000000-0000-4000-8000-000000000001';
select pg_temp.assert_true((select relationship_owner='10000000-0000-4000-8000-000000000003' from public.organizations where id='20000000-0000-4000-8000-000000000001'),'admin reassign');
select pg_temp.expect_error($q$update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000006'$q$,'23514','inactive target');
select pg_temp.expect_error($q$update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000004'$q$,'23514','finance target');
select pg_temp.expect_error($q$update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000001'$q$,'23514','admin target is not staff');
select pg_temp.expect_error($q$update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000099'$q$,'23514','unknown target');
update public.organizations set relationship_owner=null;
update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select pg_temp.assert_true((select count(*)=1 from public.staff_directory),'staff directory only self');
select pg_temp.assert_true((select count(*)=1 from public.profiles),'staff profiles only self');
insert into public.organizations(id,name,relationship_owner) values('20000000-0000-4000-8000-000000000002','Synthetic Organization B','10000000-0000-4000-8000-000000000002');
insert into public.organizations(id,name) values('20000000-0000-4000-8000-000000000003','Synthetic Unassigned');
select pg_temp.expect_error($q$insert into public.organizations(name,relationship_owner) values('Invalid','10000000-0000-4000-8000-000000000003')$q$,'42501','staff cannot create for other');
select pg_temp.expect_error($q$update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000003'$q$,'42501','staff cannot reassign');
select pg_temp.expect_error($q$update public.organizations set relationship_owner=null where id='20000000-0000-4000-8000-000000000001'$q$,'42501','staff cannot clear');
select pg_temp.expect_error($q$update public.organizations set relationship_owner='10000000-0000-4000-8000-000000000002' where id='20000000-0000-4000-8000-000000000003'$q$,'42501','staff cannot claim unassigned after creation');
select pg_temp.expect_error($q$insert into public.organizations(id,name,relationship_owner) values('20000000-0000-4000-8000-000000000001','Upsert','10000000-0000-4000-8000-000000000002') on conflict(id) do update set relationship_owner=null$q$,'42501','upsert cannot bypass');
with removed as (delete from public.organizations returning id) select pg_temp.assert_true((select count(*)=0 from removed),'staff cannot delete/reinsert to reassign');
select pg_temp.expect_error($q$update public.profiles set role='admin'$q$,'42501','no self escalation');
select pg_temp.expect_error($q$insert into public.staff_directory values('10000000-0000-4000-8000-000000000004','Forged')$q$,'42501','directory projection immutable');
select pg_temp.expect_error($q$select private.validate_organization_owner()$q$,'42501','guard not RPC callable');
update public.organizations set relationship_strength='High',potential='Low',estimated_opportunity=1234.56 where id='20000000-0000-4000-8000-000000000001';
insert into public.contacts(id,organization_id,first_name,last_name,email,contact_type,influence_level,interests,notes) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Demo','Contact','contact@example.test','Decision Maker','High','Scholarships','Synthetic note');
update public.organizations set primary_contact_id='30000000-0000-4000-8000-000000000001' where id='20000000-0000-4000-8000-000000000001';
select pg_temp.expect_error($q$update public.organizations set primary_contact_id='30000000-0000-4000-8000-000000000001' where id='20000000-0000-4000-8000-000000000002'$q$,'23503','primary contact affiliation');
select pg_temp.expect_error($q$update public.contacts set organization_id='20000000-0000-4000-8000-000000000002'$q$,'23503','primary contact cannot silently move');
select pg_temp.expect_error($q$update public.organizations set relationship_strength='Invalid'$q$,'23514','strength DB validation');
select pg_temp.expect_error($q$update public.organizations set name='   '$q$,'23514','nonblank DB validation');
select pg_temp.expect_error($q$update public.contacts set email='broken'$q$,'23514','email DB validation');
select pg_temp.expect_error($q$update public.organizations set website='javascript:alert(1)'$q$,'23514','website scheme DB validation');
update public.contacts set title='Updated Title';
select pg_temp.assert_true((select title='Updated Title' and interests='Scholarships' from public.contacts),'contact read/update preserves fields');
select pg_temp.assert_true((select relationship_strength='High' and potential='Low' and estimated_opportunity=1234.56 from public.organizations where id='20000000-0000-4000-8000-000000000001'),'organization read/update fields');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
select pg_temp.assert_true((select count(*)=0 from public.staff_directory),'finance directory empty');
select pg_temp.expect_error($q$insert into public.organizations(name) values('Denied')$q$,'42501','finance insert denied');
with changed as (update public.organizations set relationship_owner=null returning id) select pg_temp.assert_true((select count(*)=0 from changed),'finance owner update denied');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',false);
select pg_temp.assert_true((select count(*)=0 from public.staff_directory),'viewer directory empty');
with changed as (update public.organizations set relationship_owner=null returning id) select pg_temp.assert_true((select count(*)=0 from changed),'viewer owner update denied');
select pg_temp.assert_true((select count(*)=3 from public.organizations),'viewer can read organizations');
reset role;
update public.profiles set is_active=false where id='10000000-0000-4000-8000-000000000002';
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
select pg_temp.assert_true((select count(*)=1 from public.staff_directory),'deactivation sync removes directory entry');
update public.organizations set notes='Historical owner preserved' where id='20000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select pg_temp.assert_true((select count(*)=0 from public.organizations),'inactive actor cannot read');
select pg_temp.expect_error($q$insert into public.organizations(name) values('Denied')$q$,'42501','inactive actor cannot write');
reset role;
set role anon;
select pg_temp.expect_error($q$select * from public.staff_directory$q$,'42501','anonymous directory denied');
select pg_temp.expect_error($q$select * from public.organizations$q$,'42501','anonymous organizations denied');
reset role;
select pg_temp.assert_true((select count(*)=29 from pg_tables where schemaname='cbc_demo_draft' and rowsecurity),'draft tables all RLS enabled');
select pg_temp.assert_true(not has_schema_privilege('authenticated','cbc_demo_draft','USAGE'),'draft schema inaccessible to authenticated');
select pg_temp.assert_true(not exists(select 1 from information_schema.table_privileges where table_schema='cbc_demo_draft' and grantee in ('anon','authenticated','PUBLIC')),'draft tables no client grants');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
select pg_temp.expect_error($q$update public.organizations set estimated_opportunity='NaN'::numeric$q$,'23514','finite amount DB validation');
select pg_temp.expect_error($q$update public.organizations set id='20000000-0000-4000-8000-000000000099' where id='20000000-0000-4000-8000-000000000001'$q$,'42501','identity change forbidden');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
with changed as (update public.contacts set notes='Denied' returning id) select pg_temp.assert_true((select count(*)=0 from changed),'finance contact update denied');
reset role;
select pg_temp.assert_true(not has_function_privilege('authenticated','private.validate_organization_owner()','execute'),'owner guard not client callable');
select pg_temp.assert_true(not has_function_privilege('authenticated','private.sync_staff_directory()','execute'),'directory sync not client callable');
select pg_temp.assert_true(not has_function_privilege('anon','public.current_role()','execute'),'anonymous role helper denied');
select pg_temp.assert_true((select count(*)=0 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.prosecdef and not ('search_path=""'=any(p.proconfig))),'privileged helpers have empty search path');
select 'PASS ownership, directory, CRUD, validation and RLS checks' as result;
